package com.tietsync.academic;
import jakarta.persistence.*; import java.time.*; import java.util.*;
enum Role { STUDENT, FACULTY }
enum RequestStatus { PENDING, APPROVED, REJECTED, CANCELLED }
@MappedSuperclass abstract class BaseEntity { @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; @Column(nullable=false,updatable=false) Instant createdAt=Instant.now(); Instant updatedAt=Instant.now(); @PreUpdate void touch(){updatedAt=Instant.now();} }
@Entity @Table(name="users") class UserAccount extends BaseEntity { @Column(nullable=false,unique=true) String email; @Column(nullable=false) String passwordHash; @Column(nullable=false) String fullName; @Enumerated(EnumType.STRING) @Column(nullable=false) Role role; @Column(nullable=false) boolean approved=true; String rollNumber; String facultyId; String branch; Integer batchYear; String designation; String cabinLocation; String department; }
@Entity @Table(name="classrooms") class Classroom extends BaseEntity { @Column(nullable=false,unique=true) String code; String name; String building; String floor; Integer capacity; String amenities; String directions; String description; boolean demonstrationData=true; }
@Entity @Table(name="assignments") class Assignment extends BaseEntity { @ManyToOne(optional=false) UserAccount owner; String title; String category; LocalDate dueDate; boolean completed; }
@Entity @Table(name="attendance_records",uniqueConstraints=@UniqueConstraint(columnNames={"student_id","courseCode"})) class AttendanceRecord extends BaseEntity { @ManyToOne(optional=false) @JoinColumn(name="student_id") UserAccount student; String courseCode; String courseName; int attendedClasses; int totalClasses; }
@Entity @Table(name="academic_events") class AcademicEvent extends BaseEntity { String title; LocalDate eventDate; String category; String description; boolean demonstrationData=true; }
@Entity @Table(name="resources") class Resource extends BaseEntity { String title; String subject; String resourceType; String description; String externalUrl; boolean demonstrationData=true; }
@Entity @Table(name="consultation_slots",uniqueConstraints=@UniqueConstraint(columnNames={"faculty_id","slotDate","startTime"})) class ConsultationSlot extends BaseEntity { @ManyToOne(optional=false) @JoinColumn(name="faculty_id") UserAccount faculty; LocalDate slotDate; LocalTime startTime; LocalTime endTime; boolean available=true; }
@Entity @Table(name="consultation_requests",uniqueConstraints=@UniqueConstraint(columnNames={"slot_id"})) class ConsultationRequest extends BaseEntity { @ManyToOne(optional=false) @JoinColumn(name="student_id") UserAccount student; @ManyToOne(optional=false) @JoinColumn(name="faculty_id") UserAccount faculty; @ManyToOne(optional=false) @JoinColumn(name="slot_id") ConsultationSlot slot; @Enumerated(EnumType.STRING) RequestStatus status=RequestStatus.PENDING; @Column(length=1200) String description; }
@Entity @Table(name="class_schedules") class ClassSchedule extends BaseEntity { @ManyToOne(optional=false) @JoinColumn(name="owner_id") UserAccount owner; String courseCode; String courseName; String weekday; LocalTime startTime; LocalTime endTime; @ManyToOne Classroom classroom; }
